def table(headers,rows):
 return '<div class="table-wrap"><table><thead><tr>'+''.join('<th scope="col">'+h+'</th>' for h in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+str(c)+'</td>' for c in row)+'</tr>' for row in rows)+'</tbody></table></div>'
def page(file,title,body):
 (OUT/file).write_text('<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="Evidence-first gold engagement ring research. No invented prices."><meta http-equiv="Content-Security-Policy" content="default-src \'self\'; script-src \'self\'; style-src \'self\'; img-src \'self\'; object-src \'none\'; base-uri \'none\'; form-action \'none\'"><title>'+title+' · GOLD</title><link rel="stylesheet" href="style.css"></head><body><a class="skip" href="#main">Skip to content</a><aside><a class="brand" href="index.html">G<span>O</span>LD<span class="dot">.</span></a><p class="tag">ENGAGEMENT RING RESEARCH</p><nav>'+''.join(f'<a {"aria-current=page" if file==f else ""} href="{f}">{n}</a>' for f,n in nav)+'</nav><div class="aside-note">Evidence over assumptions.<br>Last research: 22 Oct 2026<br>Currency: USD</div></aside><main id="main"><div class="eyebrow">THE EVIDENCE EDIT / GOLD RESEARCH</div><h1>'+title+'</h1><section class="policy"><strong>No hallucinations. No invented prices.</strong> Only observed official-source values are recorded. Blank means unverified, never zero. Seller statements are not independent testing. Recheck for hallucinations after every review.</section>'+body+'<footer>Research, not a purchase endorsement. Prices are dated observations, not live quotes. No affiliate links. <a href="data.json">Download research JSON</a></footer></main><script src="app.js" defer></script></body></html>')
page('index.html','A clearer path to the right ring.','<p class="lead">An organized, evidence-first workspace for finding a solid gold engagement ring. Know what is confirmed. See what is missing.</p><div class="stats"><article><small>RESEARCHED SETTINGS</small><b>02</b><span>Official product pages reviewed</span></article><article><small>FULLY QUALIFIED</small><b>00</b><span>No ring meets all requirements yet</span></article><article><small>GOLD WEIGHTS VERIFIED</small><b>00</b><span>Valuation is blocked, not estimated</span></article></div><section class="split"><article><div class="eyebrow">01 / START HERE</div><h2>Read the evidence, not just the stamp.</h2><p>A karat label alone does not establish actual purity. Your acceptance rule requires explicit solid gold, weight, markings, return eligibility and independent verification.</p><a class="button" href="rings.html">Explore the research →</a></article><article class="dark"><h2>No purchase recommendation yet.</h2><p>Two white-gold settings are documented. Missing weight, solid-gold wording and hallmark evidence prevent qualification. Yellow-gold and broader seller coverage remain open research gaps.</p><a href="flagged.html">See every open issue →</a></article></section><h2>Research boundaries</h2><p>This is a bounded initial research register, not a complete market inventory. No live gold feed was verified. No independent seller-reputation audit, physical test or seller contact was completed. Missing evidence is published rather than silently inferred.</p>')
rows=[]
