page('rings.html','Ring research','<p class="lead">Two documented settings. Zero approved purchases.</p><label class="search">Filter research <input id="search" type="search" placeholder="Search name, metal, or diamond type"></label><p>Empty cells are unverified. Prices were observed on 2026-10-22; center diamond, checkout taxes and final configuration are not included or confirmed. White gold is listed separately from yellow gold; rhodium finish is disclosed by these pages.</p>'+table(['Setting / stock no.','Category','Listed metal','Observed price','Metal weight (g)','Explicit solid gold','Hallmark','Maker mark','Qualification','Checked / source'],rows)+'<p id="filter-status" aria-live="polite"></p><h2>Return eligibility matters</h2>'+table(['Seller','Observed policy','Exceptions / caution','Source'],[['Blue Nile','Eligible original, unworn items: 30 days from shipment. RMA required.','Custom, engraved, personalized, resized after initial purchase, upgrade, clearance and final-sale items excluded. Independent testing permission and item-specific eligibility unconfirmed.',link(returns)]])+'<p>Official product pages publish +1-800-242-2728 and service@bluenile.com. These are published contact details, not proof of reputation or a completed contact check.</p>')
page('calculator.html','Gold content, without guesswork.','<p class="lead">Automatic calculations only when the evidence supports them.</p><label>Select documented setting <select id="ring-select">'+''.join(f'<option value="{i}">{esc(p["name"])}</option>' for i,p in enumerate(products))+'</select></label><section class="calc"><h2 id="calc-title">Calculation unavailable</h2><p id="calc-message">Verified metal-only weight and a dated official gold quote are missing. Raw gold mass and value are intentionally blank.</p><dl><dt>Metal weight (grams)</dt><dd id="weight"></dd><dt>Nominal fine-gold mass (grams)</dt><dd id="fine"></dd><dt>Dated USD per fine-gold gram</dt><dd id="spot"></dd><dt>Theoretical contained gold value (USD)</dt><dd id="value"></dd></dl></section><h2>Method, not an appraisal</h2><p>Nominal fine-gold grams = verified gold-alloy-only grams × listed karat ÷ 24. Contained gold value = nominal fine-gold grams × verified USD per fine-gold gram. Stones, non-gold components and gross ring weights must not be counted as gold alloy. A retail setting price cannot substitute for metal weight.</p><p>Derived figures would be labeled calculations, not source facts. This does not estimate resale payout, workmanship, gemstones, fees or taxes. A listed karat is still a seller claim, not a laboratory result.</p>'+table(['Basis','Source'],[['FTC guidance distinguishes 24-karat fine gold, gold alloys and surface coatings. eCFR is government-hosted, authoritative but not the official legal edition.',link(reg)]]))
checks=[('Purity','Require stated karat; independently confirm actual purity.'),('Solid gold','Require explicit solid-gold wording; reject plated, vermeil, filled, overlay and gold-tone.'),('Markings','Require a karat stamp and maker/manufacturer mark; do not treat either as a test.'),('Weight','Require grams of gold alloy excluding stones and other components.'),('Seller','Review independent complaints and reviews; validate real contact details.'),('Price','Compare documented weight against a dated gold quote; no cheap-price conclusion without evidence.'),('Returns','Confirm independent inspection/testing permission and exclusions for resizing and custom work.'),('Payment','Prefer credit card purchase protection; avoid irreversible payments.'),('Documentation','Preserve listing, receipt, purity claims and dated evidence.'),('Arrival','Before wearing or resizing, arrange an independent jeweler’s purity and weight check.'),('Testing','Ask a professional about XRF or an appropriate gold-purity test; no single stamp proves purity.'),('Stop rule','Do not buy if independent verification and an eligible return are not allowed.')]
page('checklist.html','The buying checklist.','<p class="lead">Your requirements are the acceptance gate.</p><p>The following are project rules supplied by the owner, not claims that any seller has passed. The linked FTC guidance supplies context for gold descriptions; it does not substantiate every practical instruction, payment protection or testing method.</p>'+table(['Requirement','Project acceptance rule','Official context'],[[a,b,link(reg,'Gold-description guidance')] for a,b in checks]))
flags=[('Both settings','No weight, explicit solid-gold wording, hallmark or maker-mark evidence in retrieved pages. Fine-gold mass, complete-ring price and gold valuation blank. Neither qualifies.',products[0]['source']),('Lab-grown setting','Same missing evidence; accent diamond type does not establish metal purity.',products[1]['source']),('Returns','Independent testing permission and specific order eligibility unverified. Engraving/resizing may invalidate returns.',returns),('URL mismatch','Initial URL described a 14K yellow-gold petite solitaire; returned content was white-gold micropavé, stock 501480w14. Canonical product page checked separately. Never infer identity from a URL slug.',products[0]['source']),('Coverage and reputation','Only one seller and two white-gold settings documented; independent reputation and broader market completeness not established.',products[0]['source']),('Gold quote','No official current gold quote verified; spot price and valuation intentionally blank.',reg),('Testing','No physical ring examined. Actual purity, weight and XRF suitability/results unverified. Project instruction is not a laboratory finding.',reg)]
page('flagged.html','Flagged for Review','<p class="lead">Open issues are visible. They are not purchase approvals.</p>'+table(['Scope','Finding / required follow-up','Official context or evidence'],[[a,b,link(c)] for a,b,c in flags])+'<h2>Unavailable discovery links</h2><p>During research, an FTC consumer article and a Tiffany product URL returned page-not-found content. A Blue Nile solitaire category URL did too. They were excluded as evidence and are not linked as working product pages. No values were extracted from their URL text.</p>')
page('sources.html','Sources & verification','<p class="lead">An auditable record, with honest limits.</p>'+table(['Source','Observed evidence','Review date','Link'],[[p['id'],esc(' | '.join(p['evidence'].values())),'2026-10-22',link(p['source'])] for p in products]+[['Blue Nile returns','30-day shipment-based return window and exclusions','2026-10-22',link(returns)],['16 CFR §23.3','Gold-description and coating guidance; relevant paragraphs (a), (b)(1–3), (c)(1)','2026-10-22',link(reg)]])+'<h2>Review passes</h2><ol><li>Source pass: read official product identity, stock number, metal and setting-price text. Store dated excerpts in JSON.</li><li>Hallucination-risk pass: leave unsupported values null; no inferred weight, solid gold, hallmarks, spot quote or full-ring price.</li><li>Consistency pass: test schema, price excerpts, source domains, dates, null handling, calculator edge cases and internal links on every build.</li><li>Security pass: dependency-free static site, restrictive content security policy, escaped rendered data, no trackers, secrets, forms or external scripts.</li><li>Review recommendation: look for hallucinations again after every edit. Automated checks are guardrails, not proof of factual truth.</li></ol><p>External source content was retrieved during this session. Local audits check link structure; future availability and dynamic checkout prices cannot be guaranteed. Prices are not refreshed automatically. No claim of real-time accuracy is made.</p>')
